def render(template, values):
    """The template with its fields filled from `values`. See TASK.md."""
    result = []
    i = 0

    while i < len(template):
        char = template[i]
        if char == "{":
            if i + 1 < len(template) and template[i + 1] == "{":
                result.append("{")
                i += 2
                continue

            end = template.find("}", i + 1)
            if end == -1:
                raise ValueError("unclosed field")
            field = template[i + 1:end]
            if "{" in field:
                raise ValueError("nested field")

            if "|" in field:
                path_text, default = field.split("|", 1)
            else:
                path_text, default = field, None
            path = path_text.strip()
            if not path:
                raise ValueError("empty field")

            names = path.split(".")
            if any(not name or any(c not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_" for c in name)
                   for name in names):
                raise ValueError("invalid path")

            found = True
            value = values
            for index, name in enumerate(names):
                if isinstance(value, dict):
                    if name not in value:
                        found = False
                        break
                    value = value[name]
                elif isinstance(value, (list, tuple)) and name.isdigit():
                    numeric_index = int(name)
                    if numeric_index >= len(value):
                        found = False
                        break
                    value = value[numeric_index]
                else:
                    found = False
                    break

            if not found:
                if default is None:
                    raise KeyError(path)
                result.append(default)
            elif value is None:
                result.append("")
            elif value is True:
                result.append("true")
            elif value is False:
                result.append("false")
            else:
                result.append(str(value))
            i = end + 1
        elif char == "}":
            if i + 1 < len(template) and template[i + 1] == "}":
                result.append("}")
                i += 2
            else:
                raise ValueError("unmatched closing brace")
        else:
            result.append(char)
            i += 1

    return "".join(result)
